.disc-item:hover{background:#fbfcff;}
.disc-item:active{cursor:grabbing;}
.disc-item.dragging{opacity:.35;}
.disc-item.ghost{position:fixed;z-index:9999;pointer-events:none;opacity:.94;box-shadow:0 12px 30px rgb(20 30 50 / .24);}
.disc-item .handle{flex:0 0 auto;color:#a9b4c2;display:flex;}
.disc-item .handle svg{display:block;}
.disc-item .txt{flex:1;}
.disc-item .typ{width:15px;height:15px;border-radius:4px;flex:0 0 auto;border:1px solid rgb(0 0 0 / .08);opacity:.3;}
.disc-item .typ.d{background:var(--D);} .disc-item .typ.i{background:var(--I);}
.disc-item .typ.s{background:var(--S);} .disc-item .typ.c{background:var(--C);}
.disc-item.anchored .typ{opacity:1;box-shadow:0 0 0 2px var(--card) inset;}
.card-foot{font-weight:700;font-size:13px;color:#a4b0c3;margin-top:6px;text-align:right;}
.foot-note p{color:var(--muted);font-size:13px;margin:12px 0 0;}
.nav{display:flex;align-items:center;gap:12px;margin-top:26px;}
.nav .fill{flex:1;}
button{font-family:inherit;font-weight:700;cursor:pointer;border:1px solid var(--line);background:var(--card);color:var(--ink);padding:11px 24px;border-radius:11px;font-size:15px;transition:filter .15s,background .15s,opacity .15s;}
button:hover{filter:brightness(.98);}
button:disabled{opacity:.4;cursor:not-allowed;pointer-events:none;}
button.primary{background:linear-gradient(90deg,var(--accent),var(--accent2));border:none;color:#fff;}
button.primary:hover{filter:brightness(1.04);}
button.primary:disabled{background:linear-gradient(90deg,var(--accent),var(--accent2));opacity:.4;pointer-events:auto;}
.result{padding:6px 6px 16px;}
.result h2{text-align:center;font-size:20px;margin:22px 0 6px;}
.result .sbar{display:flex;align-items:center;gap:16px;margin:22px 22px 0;padding:18px;background:linear-gradient(135deg,#fffbe8,#fff);border:1px solid #f0e2b6;border-radius:16px;}
.result .big{font-size:44px;font-weight:800;line-height:1;}
.result .big.D{color:var(--D);} .result .big.I{color:var(--I);}
.result .big.S{color:var(--S);} .result .big.C{color:var(--C);}
.result .scoreline{font-size:14px;color:var(--muted);margin:2px 0 2px;}
.result .scoreline b{font-weight:800;color:var(--ink);}
.result .sdesc{font-size:14px;color:#3b4a64;margin-top:8px;}
.result .sdesc span{color:#15306b;font-weight:700;}
.bars{margin:24px 22px 2px;}
.bar-row{margin-bottom:16px;}
.bar-row .top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
.bar-row .nm{font-weight:700;font-size:14px;}
.bar-row .nm .swatch{width:12px;height:12px;border-radius:3px;display:inline-block;margin-right:7px;vertical-align:-2px;}
.bar-row .val{font-size:14px;color:var(--muted);font-weight:600;}
.trk{height:10px;background:#eef1f6;border-radius:99px;overflow:hidden;}
.trk > span{display:block;height:100%;width:0;border-radius:99px;transition:width .85s cubic-bezier(.22,.9,.3,1);}
.trk .d{background:linear-gradient(90deg,#ff7a7a,var(--D));} .trk .i{background:linear-gradient(90deg,#ffd680,var(--I));} .trk .s{background:linear-gradient(90deg,#89d6a6,var(--S));} .trk .c{background:linear-gradient(90deg,#7ab4ff,var(--C));}
.legend{list-style:none;padding:0;margin:22px 22px 4px;display:flex;flex-wrap:wrap;gap:12px;}
.legend li{flex:1 1 210px;background:#f6f8fb;border:1px solid var(--line);border-radius:12px;padding:12px 14px;}
.legend li b{display:flex;align-items:center;gap:7px;font-size:14px;margin-bottom:4px;}
.legend li b .sw{width:12px;height:12px;border-radius:3px;display:inline-block;}
.legend p{margin:0;font-size:12.5px;color:#3b4a64;line-height:1.5;}
.disclaimer{margin:22px 22px 6px;font-size:12.5px;color:#7a8799;line-height:1.55;}
.again{text-align:center;margin:22px 0 6px;}
