.quiz-progress{display:flex;gap:2px;overflow-x:auto;padding:6px 22px 0;}
.quiz-progress .ip{flex:0 0 auto;display:flex;flex-direction:column;justify-content:flex-end;}
.quiz-progress .ip span{width:13px;height:13px;border-radius:50%;background:#e3ebf7;transition:.35s;}
.quiz-progress .ip .tip{opacity:0;width:0;display:flex;flex-direction:column;justify-content:
  flex-end;overflow:visible;transition:.35s;background:#000;border-radius:2px;color:#fff;
  font-size:12px;padding:2px 6px;position:fixed;z-index:9999;pointer-events:none;max-width:220px;}
.quiz-progress .ip:hover .tip{width:auto;opacity:1;}
.quiz-progress .ip .tip .b{font-weight:700;font-size:13px;}
.quiz-progress .ip .tip .s{font-weight:400;}
.quiz-progress .ip.cur .tip{opacity:1;width:auto;}
.quiz-progress .ip.cur .tip .b{color:#fff;}
#step-title{font-size:15px;font-weight:700;margin:16px 0 10px;}
.disc-item .disc-item-row{display:flex;gap:9px;align-items:center;background:#fff;border:
  1px solid var(--line);border-radius:10px;padding:11px 13px;margin:5px 0;box-shadow:0 1px 3px
  rgb(23 32 51 / .05);transition:transform .15s;}
.disc-list .disc-item-row:nth-child(1){border-color:#e63e3e;}
.disc-list .disc-item-row:nth-child(2){border-color:#f5a524;}
.disc-list .disc-item-row:nth-child(3){border-color:#3aa66b;}
.disc-list .disc-item-row:nth-child(4){border-color:#2f7fd4;}
.disc-item-title{flex:0 0 auto;display:contents;}
.disc-item-title span{font-weight:700;font-size:12px;color:#5b6b7d;background:#fff;padding:2px 6px;
  border-radius:6px;border:1px solid var(--line);}
.disc-item-txt{flex:1;font-size:14px;color:#1c2530;}
.disc-item-handle{flex:0 0 auto;color:#a9b4c2;cursor:grab;}
.disc-item-handle svg{display:block;}
.disc-item-type{width:16px;height:16px;border-radius:4px;flex:0 0 auto;opacity:.85;}
.disc-item-type.d{background:#e63e3e;}
.disc-item-type.i{background:#f5a524;}
.disc-item-type.s{background:#3aa66b;}
.disc-item-type.c{background:#2f7fd4;}
.disc-item-row.dragging{opacity:.4;}
.result{display:none;background:#fff;border-radius:24px;box-shadow:var(--shadow);
  border:1px solid var(--line);overflow:hidden;}
.result h2{
  text-align:center;font-size:20px;margin-top:26px;margin-bottom:6px;}
.result .scoreline{display:flex;align-items:center;gap:14px;margin:18px 24px;padding:20px;
  background:linear-gradient(90deg,#fff,#fff5dd);border:1px solid #f0e2b6;border-radius:16px;}
.result .big{font-size:34px;font-weight:800;}
.result .big.D{color:#e63e3e;} .result .big.I{color:#f5a524;}
.result .big.S{color:#3aa66b;} .result .big.C{color:#2f7fd4;}
.result .sdesc{
  color:#5b6b7d;font-size:14px;margin-top:6px;}
.result .bars{margin:26px 25px 6px;}
.bars .bar-row .top{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;}
.bars .bar-row .top .nm{font-weight:700;font-size:14px;}
.bars .bar-row .top .val{font-size:14px;color:#5b6b7d;font-weight:600;}  
.bars .bar-row .top .nm .swatch{width:12px;height:12px;border-radius:3px;display:inline-block;
  margin-right:8px;vertical-align:-2px;}
.bars .trk{height:12px;background:#eef2f9;border-radius:99px;overflow:hidden;}
.bars .trk > span{display:block;height:100%;width:0;border-radius:99px;transition:width .85s;
  cubic-bezier(.22,.9,.3,1);}
.bars .trk .d{background:linear-gradient(90deg,#ff7a7a,#e63e3e);}
.bars .trk .i{background:linear-gradient(90deg,#ffd680,#f5a524);}
.bars .trk .s{background:linear-gradient(90deg,#89d6a6,#3aa66b);}
.bars .trk .c{background:linear-gradient(90deg,#7ab4ff,#2f7fd4);}
.legend{list-style:none;padding:0;margin:22px 24px 14px;display:flex;flex-wrap:wrap;gap:12px;}
.legend li{flex:1 1 220px;background:#f6f8fb;border:1px solid var(--line);border-radius:12px;
  padding:13px 14px;}
.legend li b{display:flex;align-items:center;gap:7px;font-size:14px;font-weight:700;margin-bottom:5px;}
.legend li b .sw{width:13px;height:13px;border-radius:3px;display:inline-flex;align-items:center;
  justify-content:center;color:#fff;font-size:11px;}
.legend li span{font-weight:400;color:#5b6b7d;font-size:12.5px;line-height:1.55;}
.disclaimer{margin:22px 22px 16px;font-size:12px;color:#7c8593;line-height:1.6;}
.btn-again{display:block;margin:18px auto 8px;background:linear-gradient(90deg,var(--accent),
  var(--accent2));border:none;color:#fff;width:240px;padding:14px;border-radius:12px;
  font-weight:700;font-size:15px;cursor:pointer;}
@media(max-width:768px){
  .disc-grid3{grid-template-columns:1fr;}
  .quiz .quiz-progress{padding:10px 16px 0;}
  .legend li{flex-basis:100%;}
  .quiz .quiz-body{padding:16px 14px;}
  #quiz-nav{padding:0 14px 18px;}
  .wrap{padding:22px 12px 44px;}
  .result .scoreline{flex-direction:column;text-align:left;}
}
