  function itemAt(x,y){
    var arr=currentItems();
    for(var i=0;i<arr.length;i++){
      var r=arr[i].getBoundingClientRect();
      if(y>=r.top && y<=r.bottom && x>=r.left && x<=r.right) return arr[i];
    }
    return null;
  }
  list.classList.add('drag-list');
  list.addEventListener('pointerdown',function(e){
    var it=e.target && e.target.closest ? e.target.closest('.disc-item'):null;
    if(!it){return;}
    // allow only via handle? for simplicity allow any
    dragItem=it; dragging=true;
    it._rect={...}
    list.style.userSelect='none';
    document.addEventListener('pointermove',onMove);
    document.addEventListener('pointerup',onUp);
  });
  function onMove(e){
    if(!dragging)return;
    var p=getPt(e);
    var target=itemAt(p.x,p.y);
