    "d": {"name": "Доминирование", "letter": "D"},
    "i": {"name": "Влияние", "letter": "I"},
    "s": {"name": "Стабильность", "letter": "S"},
    "c": {"name": "Соответствие", "letter": "C"},
}
ORDER = ["d", "i", "s", "c"]

# ---- Build data JSON blob for placeholder ----
data_blob = json.dumps(QUESTIONS, ensure_ascii=False, indent=2)
html = html.replace("PLACEHOLDER_QDATA", data_blob)

# ---- Inline the QDATA script content into a JS variable ----
# We build a JS string that assigns the questions list.
js_data = "const QUESTIONS = %s;" % json.dumps(QUESTIONS, ensure_ascii=False)

# ---- Adjective display order per question: items are already in DOM-list order ----

# ---- Types map for JS ----
js_types = "const TYPES = %s;" % json.dumps({
    "d": {"name": TYPES["d"]["name"], "letter": "D"},
    "i": {"name": TYPES["i"]["name"], "letter": "I"},
    "s": {"name": TYPES["s"]["name"], "letter": "S"},
    "c": {"name": TYPES["c"]["name"], "letter": "C"},
}, ensure_ascii=False)

# ---- JS logic ----
js = r'''
const STEP_LABELS = {q1, q2, q3, q4, q5, q6, q7, q8};

// Sub-question within a step (0..2). Each step has 3 questions (the grid3).
const GRID = [0, 1, 2]; // the 3 questions shown per step (by global index offset)
let currentStep = 0;
let currentSub = 0; // 0,1,2 -> which question in this step

// RANKS[qid] = array of 4 items {type,text} in current order; qid = step*3 + sub
const RANKS = [];
for (let s = 0; s < 8; s++) {
  const arr = [];
  for (let sub = 0; sub < 3; sub++) {
    const qidx = s * 3 + sub;
    const q = QUESTIONS[qidx];
    arr.push(q.items.map(it => ({ text: it.text, type: it.type })));
  }
  RANKS.push(arr);
}

const $ = sel => document.querySelector(sel);

function openQuiz() {
  $("#intro").style.display = "none";
  $("#quiz").style.display = "block";
  currentStep = 0; currentSub = 0;
  renderStep();
}

function qIndex(step, sub) { return step * 3 + sub; }

function renderStep() {
  const grid = $("#grid3");
  grid.innerHTML = "";
  for (let sub = 0; sub < 3; sub++) {
    const arr = RANKS[currentStep][sub];
    const card = document.createElement("div");
    card.className = "qcard";
    let listHtml = "";
    arr.forEach((it, pos) => {
      listHtml += `
        <li class="disc-item ${it.type}" data-type="${it.type}" draggable="true" data-step="${currentStep}" data-sub="${sub}" data-pos="${pos}">
          <div class="disc-pos">${pos + 1}</div>
          <div class="disc-val">
            <div class="disc-type-flag">${TYPES[it.type].letter}</div>
            <div class="disc-txt">${it.text}</div>
          </div>
          <div class="disc-item-hand">
            <svg class="dot-icon" width="16" height="16" viewBox="0 0 16 16" fill="currentColor"><circle cx="3" cy="3" r="1.6"/><circle cx="8" cy="3" r="1.6"/><circle cx="13" cy="3" r="1.6"/><circle cx="3" cy="8" r="1.6"/><circle cx="8" cy="8" r="1.6"/><circle cx="13" cy="8" r="1.6"/><circle cx="3" cy="13" r="1.6"/><circle cx="8" cy="13" r="1.6"/><circle cx="13" cy="13" r="1.6"/></svg>
          </div>
        </li>`;
    });
    card.innerHTML = `
      <div class="qcard-hd">Вопрос ${sub + 1} из 3</div>
      <ul>${listHtml}</ul>`;
    grid.appendChild(card);
    attachDrag(card);
  }
  // update heading
  $("#stepNum").textContent = (currentStep + 1);
  $("#stepLabel").textContent = "Шаг " + (currentStep + 1) + " из 8";
  updateProgress();
  updateNav();
}

function updateProgress() {
  const total = (currentStep * 3) + currentSub; // questions answered-so-far indicator
  $("#stepFill").style.width = ((currentStep) / 8 * 100) + "%";
  $("#progress2").textContent = `Вопрос ${currentStep * 3 + currentSub + 1} из 24`;
}

function updateNav() {
  $("#prevBtn").style.visibility = (currentStep === 0 && currentSub === 0) ? "hidden" : "visible";
  if (currentStep === 7 && currentSub === 2) {
    $("#nextBtn").textContent = "Получить результат";
    $("#nextBtn").onclick = submitQuiz;
  } else {
    $("#nextBtn").textContent = "Далее";
    $("#nextBtn").onclick = goToNext;
  }
}

function goToNext() {
  if (currentSub < 2) { currentSub++; }
  else { currentSub = 0; currentStep++; }
  renderStep();
}

function onPrev() {
  if (currentSub > 0) { currentSub--; }
  else if (currentStep > 0) { currentStep--; currentSub = 2; }
  renderStep();
}

// ---- Drag & drop ----
let dragEl = null;
function attachDrag(card) {
  const items = card.querySelectorAll(".disc-item");
  items.forEach(li => {
    li.addEventListener("dragstart", e => {
      dragEl = li; li.classList.add("drag");
    });
    li.addEventListener("dragend", e => {
      li.classList.remove("drag"); dragEl = null;
      reindex(card);
    });
    li.addEventListener("dragover", e => {
      e.preventDefault();
      if (dragEl && dragEl !== li) {
        const rect = li.getBoundingClientRect();
        const midY = rect.top + rect.height / 2;
        if (e.clientY < midY) { li.insertBefore(dragEl, li); }
        else { li.insertBefore(dragEl, li.nextSibling); }
      }
    });
  });
}
function reindex(card) {
  card.querySelectorAll(".disc-item").forEach((li, pos) => {
    li.setAttribute("data-pos", pos);
    li.querySelector(".disc-pos").textContent = (pos + 1);
  });
}

// ---- Submit ----
function submitQuiz() {
  const scores = { d: 0, i: 0, s: 0, c: 0 };
  for (let s = 0; s < 8; s++) {
    for (let sub = 0; sub < 3; sub++) {
      const arr = RANKS[s][sub];
      // find current DOM order within card
      const cards = $("#grid3").children;
      const card = cards[sub];
      const ordered = Array.from(card.querySelectorAll(".disc-item")).map(li => li.getAttribute("data-type"));
      const top = ordered[0];   // +1
      const bottom = ordered[3]; // -1
      scores[top] += 1;
      scores[bottom] -= 1;
    }
  }
  showResult(scores);
}

function showResult(scores) {
  $("#quiz").style.display = "none";
  $("#result").style.display = "block";
  // compute dominant
  let dom = "d", best = scores[dom];
  for (const k of ORDER) { if (scores[k] > best) { best = scores[k]; dom = k; } }
  const t = TYPES[dom];
  const letterSvg = "";
  // Build result grid
  const grid = $("#resultGrid");
  grid.innerHTML = "";
  // Dominant type card
  const typeDesc = {
    d: "Владельцы этого профиля предпочитают брать на себя ответственность, принимать решения и вести за собой. Они целеустремлены, инициативны и готовы к вызовам.",
    i: "Эти руководители излучают энергию и вдохновение, легко заводят связи и мобилизуют команду на новые идеи. Для них важны коммуникация и признание.",
    s: "Спокойные и надёчные, они ценят стабильность, последовательность и поддержку. Держатся за проверенные подходы и создают вокруг себя атмосферу доверия.",
    c: "Внимание к деталям и стандартам. Они стремятся к качеству, порядка и правильности процессов, доверяют проверенным методам.",
  };
  const emoji = { d: "🔥", i: "✨", s: "🌿", c: "💎" };
  const domCard = document.createElement("div");
  domCard.className = "typecard";
  domCard.innerHTML = `
    <div class="tc-emoji">${emoji[dom]}</div>
    <div class="tc-title">${t.name}</div>
    <div class="tc-desc">${typeDesc[dom]}</div>`;
  grid.appendChild(domCard);
  // 4 score cards
  for (const k of ORDER) {
    const val = scores[k];
    const pct = Math.round(Math.max(0, val) / 8 * 100); // normalize
    const card = document.createElement("div");
    card.className = "barcard";
    card.id = "barcard-" + k;
    card.innerHTML = `
      <div class="bc-head">
        <span class="bc-name"><span class="bc-let ${k}">${k.toUpperCase()}</span>${TYPES[k].name}</span>
        <span class="bc-pct">${val}</span>
      </div>
      <div class="bc-rank">${val === Math.max(...Object.values(scores)) ? "Ваш ведущий тип" : "Уровень проявления"}</div>
      <div class="tbar"><span class="${k}" data-w="${pct}"></span></div>`;
    grid.appendChild(card);
    // animate after paint
    setTimeout(() => {
      const span = card.querySelector(".tbar span");
      if (span) span.style.width = Math.max(6, pct) + "%";
    }, 120);
  }
  // Legend
  const leg = $("#resultLegend");
  leg.innerHTML = ORDER.map(k =>
    `<span class="leg-item"><span class="leg-swatch ${k}"></span>${TYPES[k].name}: ${scores[k]}</span>`
  ).join("");
}

// wireup
document.addEventListener("DOMContentLoaded", () => {
  $("#startBtn").addEventListener("click", openQuiz);
  $("#prevBtn").addEventListener("click", onPrev);
});
''';

js = js.replace("const STEP_LABELS = {q1, q2, q3, q4, q5, q6, q7, q8};",
                "const STEP_LABELS = %s;" % json.dumps(STEP_LABELS, ensure_ascii=False))

html = html.replace("PLACEHOLDER_JS", js)
html = html.replace("PLACEHOLDER_QDATA", js_data)

with open(OUT, "w", encoding="utf-8") as f:
    f.write(html)
print("Wrote", OUT, len(html), "bytes")

