for (let i = 0; i < 8; i++) {
  const arr = [];
  for (let j = 0; j < 3; j++) arr.push(QUESTIONS[qIndex(i,j)].items);
  RANKS.push(arr);
}
function qIndex(step, sub){ return step*3+sub; }

// Independent score computation
function compute(orderBy){
  const scores = { d:0, i:0, s:0, c:0 };
  for (let step=0; step<8; step++){
    for (let sub=0; sub<3; sub++){
      const arr = RANKS[step][sub];
      const ordered = arr.slice().sort((a,b)=>orderBy[a.type]-orderBy[b.type]);
      scores[ordered[0].type] += 1;
      scores[ordered[3].type] -= 1;
    }
  }
  return scores;
}

const orders = {
  'd>s>c>i': { d:0, s:1, c:2, i:3 },
  'c>i>d>s': { c:0, i:1, d:2, s:3 },
  's>d>i>c': { s:0, d:1, i:2, c:3 },
};

let allPass = true;
