  console.log(name, JSON.stringify(s), 'sum='+sum);
  if (sum !== 0) allPass = false;
}

const dom1 = compute({ d:0,i:1,s:2,c:3 });
console.log('sum all D first:', dom1.d+dom1.i+dom1.s+dom1.c);

console.log('RESULT', allPass ? 'PASS' : 'FAIL');

