// We answer deterministically: for each question the answer is "type order: d > i > s > c"
// i.e., top the item whose type=='d', bottom whose type=='c'. Mid two arbitrary.
function answerOrder(items){
  // items: [{type,text}]
  const order = {d:0,i:1,s:2,c:3};
  return items.slice().sort((a,b)=>order[a.type]-order[b.type]);
}

