      const lis = Array.from(card.querySelectorAll('.disc-item'));
      // reorder lis: move them so they follow answerOrder(items); compare by text
      const targetTexts = answerOrder(items).map(i=>i.text);
      // rebuild order: put lis in order of targetTexts
      const byText = {}
      lis.forEach(li=> byText[li.querySelector('.disc-txt').textContent.trim()] = li);
      const ul = card.querySelector('ul, .disc-list');
      // Note: reorder by data-pos too (score uses data ordering of DOM) - score reads querySelectorAll order not data-pos
      targetTexts.forEach(txt=>{
